请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-006

=== 用户原始指令 (query.txt) ===
整个赛事卡片背景图加文字,倒计时数字会变,点一下跳比赛,能看天气,提醒我快不行了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个赛事卡片背景图加文字,倒计时数字会变,点一下跳比赛,能看天气,提醒我快不行了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "赛事日程的唯一标识，用于查看比赛详情。",
              "sampleValue": "match-20260709-001"
            },
            "title": {
              "type": "string",
              "description": "即将开始的赛事名称。",
              "sampleValue": "城市杯半决赛"
            },
            "dtStart": {
              "type": "string",
              "description": "赛事开始时间，今天赛事使用 HH:MM 格式。",
              "sampleValue": "20:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "赛事结束时间，今天赛事使用 HH:MM 格式。",
              "sampleValue": "22:00"
            },
            "eventLocation": {
              "type": "string",
              "description": "赛事地点。",
              "sampleValue": "主体育场"
            },
            "remindTime": [
              {
                "type": "string",
                "description": "赛事提醒时间文本。",
                "sampleValue": "开赛前15分钟"
              }
            ]
          }
        ]
      },
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级。",
            "sampleValue": "良"
          }
        }
      }
    },
    "event": {
      "countdownNumber": {
        "type": "string",
        "description": "距离赛事开始的可变倒计时数字。",
        "sampleValue": "15"
      },
      "reminderText": {
        "type": "string",
        "description": "临近赛事时的短提醒文案。",
        "sampleValue": "提醒：快开赛"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动/跑步图标，可作为赛事提醒卡片的背景视觉锚点。"
    },
    {
      "src": "resources/base/media/partly_cloudy.png",
      "description": "彩色多云天气图标，可用于赛事当天的天气状态展示。"
    }
  ]
}

